cd /app && python3 -c "
from pptx import Presentation
prs = Presentation('output/final_deck.pptx')
for i, slide in enumerate(prs.slides):
    texts = []
    for s in slide.shapes:
        if s.has_text_frame:
            t = s.text_frame.text.strip()
            if t:
                texts.append(t[:120])
    print(f'--- Slide {i+1} ---')
    for t in texts[:4]:
        print(t)
    print()
"
